import pytest

from tapedeck.engine import tape


def valid_tape():
    return {
        "session": {
            "sdk": "example-sdk",
            "captured_at": "2026-01-01T00:00:00Z",
            "duration_s": 1.25,
        },
        "timeline": [{"seq": 0, "t": 0.0, "dir": "in", "value": "hello"}],
        "mocked_modules": {"example.Client": {"methods": {}}},
        "value_index": {"value-1": {"kind": "str"}},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_required_keys_match_documented_top_level_contract():
    assert tape.REQUIRED_KEYS == (
        "session",
        "timeline",
        "mocked_modules",
        "metadata",
    )


def test_infer_hierarchical_bindings_finds_capitalized_result_prefixes_only():
    paths = [
        "sdk.Client_result.chat.completions",
        "sdk.Widget_result",
        "sdk.lowercase_result.method",
        "sdk.Client_results.method",
        "sdk.Client_result_extra.method",
        "other.Service_result.operations.create",
    ]

    assert tape.infer_hierarchical_bindings(paths) == {
        "sdk.Client_result": "sdk.Client",
        "sdk.Widget_result": "sdk.Widget",
        "other.Service_result": "other.Service",
    }


def test_infer_hierarchical_bindings_handles_empty_and_repeated_paths():
    assert tape.infer_hierarchical_bindings([]) == {}

    assert tape.infer_hierarchical_bindings(
        ["package.Client_result.method", "package.Client_result.other_method"]
    ) == {"package.Client_result": "package.Client"}


@pytest.mark.parametrize("missing_key", tape.REQUIRED_KEYS)
def test_validate_tape_rejects_each_missing_required_top_level_key(missing_key):
    subject = valid_tape()
    del subject[missing_key]

    with pytest.raises(ValueError):
        tape.validate_tape(subject)


def test_validate_tape_accepts_complete_documented_tape():
    subject = valid_tape()

    assert tape.validate_tape(subject) is None


def test_validate_tape_rejects_a_non_list_timeline():
    subject = valid_tape()
    subject["timeline"] = {"seq": 0, "t": 0.0, "dir": "in"}

    with pytest.raises(ValueError):
        tape.validate_tape(subject)


@pytest.mark.parametrize("direction", ["sideways", "", None, "IN", "outbound"])
def test_validate_tape_rejects_invalid_timeline_directions(direction):
    subject = valid_tape()
    subject["timeline"][0]["dir"] = direction

    with pytest.raises(ValueError):
        tape.validate_tape(subject)


def test_load_tape_loads_json_and_validates_the_loaded_content(tmp_path):
    path = tmp_path / "recording.json"
    path.write_text(
        """{
          "session": {"sdk": "example-sdk", "captured_at": "now", "duration_s": 0},
          "timeline": [{"seq": 0, "t": 0.0, "dir": "out", "value": 42}],
          "mocked_modules": {"example.Client": {"methods": {}}},
          "value_index": {},
          "metadata": {"capture_mode": "value_capture", "prefer_return_value": false}
        }""",
        encoding="utf-8",
    )

    assert tape.load_tape(str(path)) == {
        "session": {"sdk": "example-sdk", "captured_at": "now", "duration_s": 0},
        "timeline": [{"seq": 0, "t": 0.0, "dir": "out", "value": 42}],
        "mocked_modules": {"example.Client": {"methods": {}}},
        "value_index": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": False,
        },
    }


def test_load_tape_does_not_accept_a_file_missing_required_tape_data(tmp_path):
    path = tmp_path / "incomplete.json"
    path.write_text(
        """{
          "session": {},
          "timeline": [],
          "mocked_modules": {}
        }""",
        encoding="utf-8",
    )

    with pytest.raises(ValueError):
        tape.load_tape(str(path))


def test_build_tape_copies_recorder_data_and_session_metadata():
    class Recorder:
        timeline = [{"seq": 0, "t": 0.0, "dir": "in", "args": ["x"]}]
        mocked_modules = {"sdk.Client": {"methods": {"create": {"return": "ok"}}}}
        value_index = {"ref-1": {"value": "x"}}
        nested_schemas = {"sdk.Client": {"type": "object"}}
        capture_mode = "value_capture"
        prefer_return_value = False

    session_meta = {
        "sdk": "sdk",
        "captured_at": "2026-01-01T00:00:00Z",
        "duration_s": 3.5,
    }

    result = tape.build_tape(Recorder(), session_meta)

    assert result["session"] == session_meta
    assert result["timeline"] == Recorder.timeline
    assert result["mocked_modules"] == Recorder.mocked_modules
    assert result["value_index"] == Recorder.value_index
    assert result["metadata"] == {
        "capture_mode": "value_capture",
        "prefer_return_value": False,
    }
    assert result["nested_schemas"] == Recorder.nested_schemas
    tape.validate_tape(result)


