import pytest

from tapedeck.engine import serialize


def _contains_text(value, needle):
    if isinstance(value, str):
        return needle in value
    if isinstance(value, dict):
        return any(
            _contains_text(key, needle) or _contains_text(item, needle)
            for key, item in value.items()
        )
    if isinstance(value, (list, tuple)):
        return any(_contains_text(item, needle) for item in value)
    return False


def test_secret_key_pattern_is_case_insensitive_and_matches_embedded_secret_names():
    assert serialize.SECRET_KEY_RE.search("API_TOKEN")
    assert serialize.SECRET_KEY_RE.search("clientRefreshValue")
    assert serialize.SECRET_KEY_RE.search("AuthorizationHeader")
    assert not serialize.SECRET_KEY_RE.search("display_name")


def test_redactor_collects_secret_named_environment_values_and_extra_values():
    redactor = serialize.Redactor.from_environ(
        {
            "API_TOKEN": "alpha-secret",
            "databasePassword": "bravo-secret",
            "DISPLAY_NAME": "ordinary-value",
        },
        extra=("charlie-secret",),
    )

    scrubbed = redactor.scrub(
        "token=alpha-secret password=bravo-secret extra=charlie-secret "
        "name=ordinary-value"
    )

    assert "alpha-secret" not in scrubbed
    assert "bravo-secret" not in scrubbed
    assert "charlie-secret" not in scrubbed
    assert "token=" in scrubbed
    assert "password=" in scrubbed
    assert "extra=" in scrubbed
    assert "ordinary-value" in scrubbed


def test_redactor_ignores_empty_secrets_and_handles_overlapping_values():
    redactor = serialize.Redactor.from_environ(
        {
            "API_KEY": "",
            "TOKEN_SHORT": "abc",
            "TOKEN_LONG": "abcd",
        }
    )

    assert redactor.scrub("ordinary text") == "ordinary text"

    scrubbed = redactor.scrub("credentials: abcd and abc")
    assert "abcd" not in scrubbed
    assert "abc" not in scrubbed
    assert "credentials:" in scrubbed
    assert " and " in scrubbed


def test_snapshot_drops_secret_named_dict_keys_and_scrubs_nested_values():
    redactor = serialize.Redactor.from_environ({"SERVICE_TOKEN": "top-secret"})
    schemas = {}

    result = serialize.snapshot(
        {
            "password": "should not appear",
            "ClientToken": "also should not appear",
            "message": "Authorization: Bearer top-secret",
            "nested": {
                "api_key": "hidden",
                "still_here": "top-secret appears here too",
            },
            "items": ("top-secret", {"refresh_token": "hidden"}),
        },
        redactor,
        schemas,
    )

    assert "password" not in result
    assert "ClientToken" not in result
    assert result["nested"].keys() == {"still_here"}
    assert result["items"][1] == {}
    assert isinstance(result["items"], list)
    assert "Authorization: Bearer " in result["message"]
    assert not _contains_text(result, "top-secret")
    assert not _contains_text(result, "should not appear")
    assert not _contains_text(result, "also should not appear")
    assert schemas == {}


def test_snapshot_of_object_includes_public_attributes_and_records_schema():
    class Record:
        def __init__(self):
            self.count = 3
            self.label = "example"
            self._private = "do not serialize"

    schemas = {}
    result = serialize.snapshot(
        Record(),
        serialize.Redactor.from_environ({}),
        schemas,
    )

    assert result == {
        "__type__": "Record",
        "count": 3,
        "label": "example",
    }
    assert schemas == {
        "Record": {
            "count": "int",
            "label": "str",
        }
    }


def test_snapshot_redacts_secret_values_inside_object_attributes():
    class CredentialsHolder:
        def __init__(self):
            self.description = "uses runtime-secret"
            self.count = 1

    schemas = {}
    result = serialize.snapshot(
        CredentialsHolder(),
        serialize.Redactor.from_environ({"ACCESS_TOKEN": "runtime-secret"}),
        schemas,
    )

    assert result["__type__"] == "CredentialsHolder"
    assert result["count"] == 1
    assert "runtime-secret" not in result["description"]
    assert "uses " in result["description"]
    assert schemas["CredentialsHolder"] == {
        "description": "str",
        "count": "int",
    }


