def test_snapshot_limits_nested_sequence_traversal_instead_of_descending_forever():
    value = 0
    for _ in range(100):
        value = [value]

    result = serialize.snapshot(
        value,
        serialize.Redactor.from_environ({}),
        {},
    )

    terminal = result
    while isinstance(terminal, list):
        assert len(terminal) == 1
        terminal = terminal[0]

    assert isinstance(terminal, str)
    assert terminal.startswith("[")
    assert terminal.endswith("]")
    assert "0" in terminal

