import pytest

from tapedeck.engine import serialize


class SnapshotExample:
    def __init__(self):
        self.name = "Ada"
        self.count = 3
        self.api_token = "object-secret"
        self._private_note = "must not be serialized"


class SnapshotChild:
    def __init__(self, label):
        self.label = label


class SnapshotParent:
    def __init__(self, child):
        self.child = child
        self.children = [child]


def test_redactor_collects_secret_named_environment_values_and_extras():
    redactor = serialize.Redactor.from_environ(
        {
            "SERVICE_TOKEN": "environment-secret",
            "DATABASE_PASSWORD": "db-password",
            "PUBLIC_SETTING": "ordinary-public-value",
        },
        extra=("extra-secret",),
    )

    scrubbed = redactor.scrub(
        "before environment-secret / db-password / extra-secret after"
    )

    assert "environment-secret" not in scrubbed
    assert "db-password" not in scrubbed
    assert "extra-secret" not in scrubbed
    assert "before " in scrubbed
    assert " after" in scrubbed
    assert redactor.scrub("ordinary-public-value remains visible") == (
        "ordinary-public-value remains visible"
    )


def test_redactor_ignores_empty_secrets_and_does_not_leak_suffix_of_overlapping_secret():
    redactor = serialize.Redactor.from_environ(
        {
            "SHORT_TOKEN": "abc",
            "LONG_TOKEN": "abcdef",
            "EMPTY_PASSWORD": "",
        },
        extra=("",),
    )

    scrubbed = redactor.scrub("left abcdef right")

    assert "abc" not in scrubbed
    assert "abcdef" not in scrubbed
    assert "def" not in scrubbed
    assert "left " in scrubbed
    assert " right" in scrubbed
    assert redactor.scrub("plain text") == "plain text"


def test_snapshot_drops_secret_named_dict_keys_and_scrubs_nested_strings():
    secret = "very-sensitive-value"
    redactor = serialize.Redactor.from_environ({"API_KEY": secret})
    schemas = {}
    value = {
        "username": "alice",
        "password": "literal-password",
        "Authorization_Header": "Bearer should-not-appear",
        "nested": {
            "apiKey": secret,
            "credential_hint": "also omitted",
            "message": "hello very-sensitive-value world",
        },
        "items": [secret, 7, None, True],
    }

    result = serialize.snapshot(value, redactor, schemas)

    assert set(result) == {"username", "nested", "items"}
    assert result["username"] == "alice"
    assert set(result["nested"]) == {"message"}
    assert "very-sensitive-value" not in result["nested"]["message"]
    assert "hello " in result["nested"]["message"]
    assert " world" in result["nested"]["message"]
    assert result["items"][1:] == [7, None, True]
    assert "very-sensitive-value" not in result["items"][0]
    assert schemas == {}

    # Taking a snapshot must not destructively redact the caller's runtime value.
    assert value["password"] == "literal-password"
    assert value["nested"]["apiKey"] == secret


def test_snapshot_serializes_public_object_attributes_and_records_schema():
    redactor = serialize.Redactor.from_environ({}, extra=("object-secret",))
    schemas = {}

    result = serialize.snapshot(SnapshotExample(), redactor, schemas)

    assert set(result) == {"__type__", "name", "count", "api_token"}
    assert result["__type__"] == "SnapshotExample"
    assert result["name"] == "Ada"
    assert result["count"] == 3
    assert "object-secret" not in result["api_token"]
    assert "_private_note" not in result
    assert schemas == {
        "SnapshotExample": {
            "name": "str",
            "count": "int",
            "api_token": "str",
        }
    }


def test_snapshot_recurses_through_objects_and_lists_and_records_each_schema():
    child = SnapshotChild("nested child")
    parent = SnapshotParent(child)
    schemas = {}
    redactor = serialize.Redactor.from_environ({})

    result = serialize.snapshot(parent, redactor, schemas)

    assert result == {
        "__type__": "SnapshotParent",
        "child": {
            "__type__": "SnapshotChild",
            "label": "nested child",
        },
        "children": [
            {
                "__type__": "SnapshotChild",
                "label": "nested child",
            }
        ],
    }
    assert schemas == {
        "SnapshotParent": {
            "child": "SnapshotChild",
            "children": "list",
        },
        "SnapshotChild": {
            "label": "str",
        },
    }


