def test_snapshot_stringifies_mapping_keys_to_keep_dict_snapshots_json_safe():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}
    value = {42: "answer", None: "missing"}

    result = serialize.snapshot(value, redactor, schemas)

    assert result == {"42": "answer", "None": "missing"}
    assert all(isinstance(key, str) for key in result)
    assert value == {42: "answer", None: "missing"}
    assert schemas == {}


def test_snapshot_increases_depth_for_nested_list_items_until_it_truncates():
    value = "deep leaf"
    for _ in range(100):
        value = [value]

    result = serialize.snapshot(
        value,
        serialize.Redactor.from_environ({}),
        {},
    )

    list_layers = 0
    truncated_value = result
    while isinstance(truncated_value, list):
        assert len(truncated_value) == 1
        list_layers += 1
        truncated_value = truncated_value[0]

    assert list_layers < 100
    assert isinstance(truncated_value, str)
    assert truncated_value.startswith("[")

