from tapedeck.engine import serialize


def test_secret_key_pattern_recognizes_common_variants_without_matching_unrelated_keys():
    for key in (
        "TOKEN",
        "client_secret",
        "dbPassword",
        "API_KEY",
        "apikey",
        "Authorization",
        "credential_file",
        "refreshToken",
    ):
        assert serialize.SECRET_KEY_RE.search(key)

    assert serialize.SECRET_KEY_RE.search("monkey") is None
    assert serialize.SECRET_KEY_RE.search("username") is None


def test_redactor_collects_sensitive_environment_values_and_extra_values():
    redactor = serialize.Redactor.from_environ(
        {
            "SERVICE_TOKEN": "env-credential-123",
            "normal_setting": "ordinary-value",
            "EMPTY_SECRET": "",
        },
        extra=(value for value in ("extra-credential-456",)),
    )

    scrubbed = redactor.scrub(
        "prefix env-credential-123 middle extra-credential-456 suffix"
    )

    assert "env-credential-123" not in scrubbed
    assert "extra-credential-456" not in scrubbed
    assert scrubbed.startswith("prefix ")
    assert scrubbed.endswith(" suffix")
    assert redactor.scrub("ordinary-value") == "ordinary-value"
    assert redactor.scrub("plain text") == "plain text"


def test_snapshot_redacts_string_values_and_drops_secret_looking_dict_keys_recursively():
    secret = "super-secret-value"
    redactor = serialize.Redactor.from_environ({"MY_API_KEY": secret})
    schemas = {}

    result = serialize.snapshot(
        {
            "safe": "before super-secret-value after",
            "token": "should not appear",
            "clientSecret": "should not appear",
            "nested": {
                "authorization_header": "should not appear",
                "refresh_token": "should not appear",
                "value": "embedded super-secret-value here",
            },
            "monkey": "this is not a secret-looking key",
            "pair": (1, "two"),
        },
        redactor,
        schemas,
    )

    assert set(result) == {"safe", "nested", "monkey", "pair"}
    assert set(result["nested"]) == {"value"}
    assert result["monkey"] == "this is not a secret-looking key"
    assert result["pair"] == [1, "two"]
    assert secret not in result["safe"]
    assert secret not in result["nested"]["value"]
    assert result["safe"].startswith("before ")
    assert result["safe"].endswith(" after")
    assert result["nested"]["value"].startswith("embedded ")
    assert result["nested"]["value"].endswith(" here")
    assert schemas == {}


def test_snapshot_preserves_json_scalars_and_redacts_strings_inside_containers():
    redactor = serialize.Redactor.from_environ({"PASSWORD": "pw-123"})
    schemas = {}

    result = serialize.snapshot(
        [None, True, False, 7, 2.5, "pw-123", {"message": "xpw-123y"}],
        redactor,
        schemas,
    )

    assert result[:5] == [None, True, False, 7, 2.5]
    assert "pw-123" not in result[5]
    assert "pw-123" not in result[6]["message"]
    assert result[6]["message"].startswith("x")
    assert result[6]["message"].endswith("y")
    assert schemas == {}


def test_snapshot_of_objects_uses_public_attributes_and_builds_schemas_for_nested_types():
    class Address:
        def __init__(self):
            self.city = "Paris"
            self.zip_code = 75001
            self._internal_note = "not public"

    class User:
        def __init__(self):
            self.name = "Ada"
            self.active = True
            self.address = Address()
            self.tags = ["admin", "tester"]
            self._cache = {"ignored": True}

    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    result = serialize.snapshot(User(), redactor, schemas)

    assert result == {
        "__type__": "User",
        "name": "Ada",
        "active": True,
        "address": {
            "__type__": "Address",
            "city": "Paris",
            "zip_code": 75001,
        },
        "tags": ["admin", "tester"],
    }
    assert schemas == {
        "User": {
            "name": "str",
            "active": "bool",
            "address": "Address",
            "tags": "list",
        },
        "Address": {
            "city": "str",
            "zip_code": "int",
        },
    }


