def test_snapshot_increases_depth_through_nested_lists_until_the_depth_limit():
    secret = "nested-depth-secret"
    leaf = {"marker": secret}
    value = leaf

    for _ in range(serialize._MAX_DEPTH + 1):
        value = [value]

    redactor = serialize.Redactor.from_environ({"SESSION_TOKEN": secret})
    schemas = {}

    result = serialize.snapshot(value, redactor, schemas)

    for _ in range(serialize._MAX_DEPTH + 1):
        assert isinstance(result, list)
        assert len(result) == 1
        result = result[0]

    assert result == redactor.scrub(repr(leaf))
    assert secret not in result
    assert schemas == {}


