def test_build_tape_returns_complete_tape_and_derives_bindings_from_recorder_paths():
    class RecorderWithConstructorResultPath:
        timeline = [
            {"seq": 0, "t": 0.0, "dir": "in", "method": "connect"},
            {"seq": 1, "t": 0.1, "dir": "out", "value": "connected"},
        ]
        mocked_modules = {
            "sdk.Client_result.transport": {
                "methods": {"send": {"return_value": "ok"}}
            }
        }
        value_index = {"result-1": {"type": "str", "value": "connected"}}
        nested_schemas = {}
        schemas = {}
        capture_mode = "value_capture"
        prefer_return_value = True
        _capture_mode = "value_capture"
        _prefer_return_value = True
        _container_paths = ["sdk.Client_result.transport"]

        def get_container_paths_added(self):
            return list(self._container_paths)

    session = {
        "sdk": "example",
        "captured_at": "2026-01-01T00:00:00Z",
        "duration_s": 0.1,
    }

    built = tape.build_tape(RecorderWithConstructorResultPath(), session)

    assert built["session"] == session
    assert built["timeline"] == [
        {"seq": 0, "t": 0.0, "dir": "in", "method": "connect"},
        {"seq": 1, "t": 0.1, "dir": "out", "value": "connected"},
    ]
    assert built["mocked_modules"] == {
        "sdk.Client_result.transport": {
            "methods": {"send": {"return_value": "ok"}}
        }
    }
    assert built["value_index"] == {
        "result-1": {"type": "str", "value": "connected"}
    }
    assert built["hierarchical_bindings"] == {
        "sdk.Client_result": "sdk.Client"
    }
    assert set(tape.REQUIRED_KEYS).issubset(built)

import pytest

import tapedeck.engine.serialize as serialize


class Profile:
    def __init__(self, name, visits, note):
        self.name = name
        self.visits = visits
        self.note = note
        self._internal_id = "must-not-be-snapshotted"


class Child:
    def __init__(self, value):
        self.value = value


class Parent:
    def __init__(self, child):
        self.child = child
        self.enabled = True


def test_from_environ_uses_secret_named_variables_and_extra_values_only():
    env_secret = "env-secret-9f2d"
    extra_secret = "manual-secret-8a71"
    ordinary_value = "ordinary-value-44c0"

    redactor = serialize.Redactor.from_environ(
        {
            "SERVICE_API_TOKEN": env_secret,
            "ordinary_setting": ordinary_value,
        },
        extra=[extra_secret],
    )

    text = (
        f"token={env_secret}; extra={extra_secret}; "
        f"ordinary={ordinary_value}; ending"
    )
    scrubbed = redactor.scrub(text)

    assert env_secret not in scrubbed
    assert extra_secret not in scrubbed
    assert ordinary_value in scrubbed
    assert scrubbed.startswith("token=")
    assert scrubbed.endswith("; ending")


def test_redactor_handles_overlapping_secret_values_without_leaking_suffix():
    short_secret = "alpha"
    long_secret = "alpha-bravo-charlie"

    redactor = serialize.Redactor.from_environ(
        {
            "FIRST_TOKEN": short_secret,
            "SECOND_TOKEN": long_secret,
        }
    )

    scrubbed = redactor.scrub(f"credentials: {long_secret} / {short_secret}")

    assert long_secret not in scrubbed
    assert short_secret not in scrubbed
    assert "bravo-charlie" not in scrubbed
    assert scrubbed.startswith("credentials: ")


def test_redactor_ignores_empty_secret_values():
    redactor = serialize.Redactor.from_environ(
        {
            "EMPTY_TOKEN": "",
            "NORMAL_SETTING": "not-a-secret",
        }
    )

    assert redactor.scrub("unchanged text") == "unchanged text"


def test_snapshot_recurses_through_containers_drops_secret_keys_and_does_not_mutate_input():
    secret = "credential-value-1b3e"
    redactor = serialize.Redactor.from_environ({"DATABASE_PASSWORD": secret})
    schemas = {}
    value = {
        "safe": [
            7,
            True,
            None,
            f"before-{secret}-after",
            ("tuple-value", 4),
        ],
        "Authorization": f"Bearer {secret}",
        "nested": {
            "apiKey": secret,
            "visible": f"visible-{secret}",
        },
    }

    result = serialize.snapshot(value, redactor, schemas)

    assert "Authorization" not in result
    assert "apiKey" not in result["nested"]
    assert result["safe"][0:3] == [7, True, None]
    assert result["safe"][4] == ["tuple-value", 4]
    assert secret not in result["safe"][3]
    assert result["safe"][3].startswith("before-")
    assert result["safe"][3].endswith("-after")
    assert secret not in result["nested"]["visible"]
    assert result["nested"]["visible"].startswith("visible-")

    assert value["Authorization"] == f"Bearer {secret}"
    assert value["nested"]["apiKey"] == secret
    assert schemas == {}


def test_snapshot_of_object_uses_public_attributes_and_records_schema():
    secret = "profile-note-secret-77"
    redactor = serialize.Redactor.from_environ({"NOTE_TOKEN": secret})
    schemas = {}
    profile = Profile("Ada", 3, f"note:{secret}:done")

    result = serialize.snapshot(profile, redactor, schemas)

    assert result["__type__"] == "Profile"
    assert result["name"] == "Ada"
    assert result["visits"] == 3
    assert "_internal_id" not in result
    assert secret not in result["note"]
    assert result["note"].startswith("note:")
    assert result["note"].endswith(":done")
    assert schemas["Profile"] == {
        "name": "str",
        "visits": "int",
        "note": "str",
    }


def test_snapshot_registers_schemas_for_nested_objects():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}
    value = Parent(Child("nested"))

    result = serialize.snapshot(value, redactor, schemas)

    assert result == {
        "__type__": "Parent",
        "child": {
            "__type__": "Child",
            "value": "nested",
        },
        "enabled": True,
    }
    assert schemas["Parent"] == {
        "child": "Child",
        "enabled": "bool",
    }
    assert schemas["Child"] == {
        "value": "str",
    }


