def test_snapshot_of_mapping_preserves_all_visible_entries_as_a_new_mapping():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}
    value = {
        "first": 1,
        "nested": {"second": 2},
        "items": ["third", 4],
    }

    result = serialize.snapshot(value, redactor, schemas)

    assert result == {
        "first": 1,
        "nested": {"second": 2},
        "items": ["third", 4],
    }
    assert result is not value
    assert result["nested"] is not value["nested"]
    assert result["items"] is not value["items"]


