def test_snapshot_of_deep_list_stops_expansion_before_reaching_nested_object():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    class DeepPayload:
        def __init___added(self):
            self.value = "reachable-only-without-depth-limit"

        def __repr__(self):
            return "DeepPayload(marker)"

    value = DeepPayload()
    for _ in range(100):
        value = [value]

    result = serialize.snapshot(value, redactor, schemas)

    terminal = result
    while isinstance(terminal, list):
        assert len(terminal) == 1
        terminal = terminal[0]

    assert isinstance(terminal, str)
    assert "DeepPayload(marker)" in terminal
    assert schemas == {}


